#[derive(Clone, Copy, Debug)]
enum End1aBingoStep {
    Start,
    OnInit,
    OnTouch,
}

fn end1a_bingo_run(ctx: &Ctx, mut step: End1aBingoStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            End1aBingoStep::Start => {
                step = End1aBingoStep::OnInit;
                continue 'machine;
            }
            End1aBingoStep::OnInit => {
                ctx.call(Function::DisableNpc, vec![Val::from("end1a#bingo")])?;
                ctx.call(Function::DisableNpc, vec![Val::from("end1b#bingo")])?;
                ctx.call(Function::DisableNpc, vec![Val::from("end1c#bingo")])?;
                ctx.call(Function::DisableNpc, vec![Val::from("end1d#bingo")])?;
                ctx.call(Function::DisableNpc, vec![Val::from("end1e#bingo")])?;
                return Err(Stop::End);
            }
            End1aBingoStep::OnTouch => {
                if ctx.var("hg_ma1").get()? == 6 {
                    ctx.call(Function::Warp, vec![Val::from("que_bingo"), Val::from(45), Val::from(186)])?;
                } else {
                    ctx.call(Function::Warp, vec![Val::from("que_bingo"), Val::from(40), Val::from(121)])?;
                }
                return Err(Stop::End);
            }
        }
    }
}

pub fn end1a_bingo(ctx: &Ctx) -> Script {
    end1a_bingo_run(ctx, End1aBingoStep::Start, Vec::new()).map(|_| ())
}

pub fn end1a_bingo_oninit(ctx: &Ctx) -> Script {
    end1a_bingo_run(ctx, End1aBingoStep::OnInit, Vec::new()).map(|_| ())
}

pub fn end1a_bingo_ontouch(ctx: &Ctx) -> Script {
    end1a_bingo_run(ctx, End1aBingoStep::OnTouch, Vec::new()).map(|_| ())
}

