#[derive(Clone, Copy, Debug)]
enum Go3BingoStep {
    Start,
    OnTouch,
}

fn go3_bingo_run(ctx: &Ctx, mut step: Go3BingoStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            Go3BingoStep::Start => {
                step = Go3BingoStep::OnTouch;
                continue 'machine;
            }
            Go3BingoStep::OnTouch => {
                'b1: {
                    let subject1 = ctx.var("$@hu_bingob").get()?;
                    let mut matched1 = false;
                    let no_case1 = !subject1.loosely_equals(&Val::from(0))
                        && !subject1.loosely_equals(&Val::from(1))
                        && !subject1.loosely_equals(&Val::from(2))
                        && !subject1.loosely_equals(&Val::from(3))
                        && !subject1.loosely_equals(&Val::from(4));
                    if !matched1 && subject1.loosely_equals(&Val::from(0)) {
                        matched1 = true;
                    }
                    if matched1 {
                        ctx.call(Function::Warp, vec![Val::from("que_bingo"), Val::from(49), Val::from(125)])?;
                        break 'b1;
                    }
                    if !matched1 && subject1.loosely_equals(&Val::from(1)) {
                        matched1 = true;
                    }
                    if matched1 {
                        ctx.call(Function::Warp, vec![Val::from("que_bingo"), Val::from(53), Val::from(121)])?;
                        break 'b1;
                    }
                    if !matched1 && subject1.loosely_equals(&Val::from(2)) {
                        matched1 = true;
                    }
                    if matched1 {
                        ctx.call(Function::Warp, vec![Val::from("que_bingo"), Val::from(51), Val::from(116)])?;
                        break 'b1;
                    }
                    if !matched1 && subject1.loosely_equals(&Val::from(3)) {
                        matched1 = true;
                    }
                    if matched1 {
                        ctx.call(Function::Warp, vec![Val::from("que_bingo"), Val::from(46), Val::from(116)])?;
                        break 'b1;
                    }
                    if !matched1 && subject1.loosely_equals(&Val::from(4)) {
                        matched1 = true;
                    }
                    if matched1 {
                        ctx.call(Function::Warp, vec![Val::from("que_bingo"), Val::from(45), Val::from(121)])?;
                        break 'b1;
                    }
                }
                ctx.var("$@hu_bingob").set((ctx.var("$@hu_bingob").get()? + Val::from(1)))?;
                if ctx.var("$@hu_bingob").get()? == 5 {
                    ctx.var("$@hu_bingob").set(Val::from(0))?;
                }
                return Err(Stop::End);
            }
        }
    }
}

pub fn go3_bingo(ctx: &Ctx) -> Script {
    go3_bingo_run(ctx, Go3BingoStep::Start, Vec::new()).map(|_| ())
}

pub fn go3_bingo_ontouch(ctx: &Ctx) -> Script {
    go3_bingo_run(ctx, Go3BingoStep::OnTouch, Vec::new()).map(|_| ())
}

